  const at = a.lastIndexOf('@')
  const userinfo = at < 0 ? undefined : a.slice(0, at)
  const rest = a.slice(at + 1)
  const colon = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  if (colon < 0) return { userinfo, host: rest, port: undefined }
  return { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
}

